#!/usr/bin/env python3
"""Compute ground truth for CSX-006_Q2 from package-local files."""

from __future__ import annotations

import csv
import json
from pathlib import Path
from typing import Any


TASK_ID = "CSX-006_Q2"
PACKAGE_ID = "CSX-006"
TARGET_FAMILY = "expert_error_attribution"

EVENT_WINDOW_SOURCE = (
    "data/event_reports/"
    "event_reports_003_Locked_event_anchor_March-April_2024_West_Africa_and_Sahel_humid_heat_wave.json"
)
CORRECT_SOURCE = "data/physical_hazard/physical_hazard_001_Open-Meteo_historical_archive.json"
WRONG_SOURCE = "data/physical_hazard/physical_hazard_002_ERA5-Land_hourly_aggregate_stats.json"
REJECTED_ALTERNATIVES = {
    "data/physical_hazard/physical_hazard_004_GPM_IMERG_V07_event_accumulated_precipitation.json": (
        "precipitation-only event accumulation; no heat-stress variables"
    ),
    "data/physical_hazard/physical_hazard_006_CHIRPS_daily_event_accumulated_precipitation.json": (
        "precipitation-only event accumulation; no heat-stress variables"
    ),
    "data/remote_sensing/remote_sensing_003_Google_Satellite_Embedding_annual_cosine-change_stats.json": (
        "annual remote-sensing change statistic; no event-window hourly or nightly heat fields"
    ),
    "data/physical_hazard/physical_hazard_008_Sentinel-2_SR_Harmonized_dNBR.json": (
        "burn-index pre/post statistic; no apparent-temperature or minimum-temperature fields"
    ),
}
SOURCE_FILES = [
    "metadata/event.json",
    "metadata/files.csv",
    "metadata/sources.csv",
    EVENT_WINDOW_SOURCE,
    CORRECT_SOURCE,
    WRONG_SOURCE,
    *REJECTED_ALTERNATIVES.keys(),
]


def repo_root() -> Path:
    return Path(__file__).resolve().parents[3]


def package_dir() -> Path:
    return repo_root() / "event_packages" / "standard_event_packages" / "packages" / PACKAGE_ID


def task_dir() -> Path:
    return Path(__file__).resolve().parent


def read_json(package: Path, rel_path: str) -> Any:
    return json.loads((package / rel_path).read_text(encoding="utf-8-sig"))


def require_manifest_paths(package: Path, rel_paths: list[str]) -> None:
    with (package / "metadata/files.csv").open(newline="", encoding="utf-8-sig") as handle:
        manifest_paths = {row["relative_path"] for row in csv.DictReader(handle)}
    for rel_path in rel_paths:
        if rel_path.startswith("metadata/"):
            continue
        if rel_path not in manifest_paths:
            raise ValueError(f"Source file is not listed in metadata/files.csv: {rel_path}")


def has_path(obj: Any, field_path: str) -> bool:
    current = obj
    for part in field_path.split("."):
        if not isinstance(current, dict) or part not in current:
            return False
        current = current[part]
    return True


def count_ge(values: list[Any], threshold: float) -> int:
    return sum(float(value) >= threshold for value in values)


def main() -> None:
    package = package_dir()
    require_manifest_paths(package, SOURCE_FILES)

    event = read_json(package, "metadata/event.json")
    if event.get("package_id") != PACKAGE_ID:
        raise ValueError("Unexpected package_id in metadata/event.json")
    if event.get("hazard_family") != "heat_wave_urban_heat":
        raise ValueError("Unexpected hazard family")

    anchor = read_json(package, EVENT_WINDOW_SOURCE)
    correct = read_json(package, CORRECT_SOURCE)
    wrong = read_json(package, WRONG_SOURCE)

    required_fields = ["hourly.apparent_temperature", "daily.temperature_2m_min"]
    missing_required_fields = [field for field in required_fields if not has_path(wrong, field)]
    if not missing_required_fields:
        raise ValueError("The substitute source unexpectedly contains all required fields")

    apparent_values = [float(value) for value in correct["hourly"]["apparent_temperature"]]
    air_values = [float(value) for value in correct["hourly"]["temperature_2m"]]
    tmin_values = [float(value) for value in correct["daily"]["temperature_2m_min"]]

    max_apparent = max(apparent_values)
    hours_apparent_ge_40 = count_ge(apparent_values, 40.0)
    warm_nights = count_ge(tmin_values, 27.0)
    max_air = max(air_values)
    wrong_temperature = float(wrong["stats"]["temperature_2m_max_c_max"])
    temperature_difference = max_air - wrong_temperature

    corrected_label = (
        "sustained_apparent_heat_with_warm_night_exposure"
        if max_apparent >= 42.0 and hours_apparent_ge_40 >= 12 and warm_nights >= 5
        else "thresholds_not_met"
    )

    primary_gt = {
        "answer_type": "expert_error_attribution",
        "audit_ruling": "source_swap_fails",
        "error_class": "missing_variable",
        "correct_source": CORRECT_SOURCE,
        "wrong_source": WRONG_SOURCE,
        "event_window_source": EVENT_WINDOW_SOURCE,
        "event_window": {
            "start_date": anchor["temporal_window"]["start_date"],
            "end_date": anchor["temporal_window"]["end_date"],
        },
        "first_missing_variable": missing_required_fields[0],
        "missing_required_fields": missing_required_fields,
        "corrected_answer": {
            "label": corrected_label,
            "metrics": {
                "max_apparent_temperature_degC": round(max_apparent, 1),
                "hours_apparent_temperature_ge_40c": int(hours_apparent_ge_40),
                "warm_nights_tmin_ge_27c": int(warm_nights),
                "max_air_temperature_degC": round(max_air, 1),
            },
        },
        "wrong_source_numeric_impact": {
            "wrong_available_temperature_field": "stats.temperature_2m_max_c_max",
            "wrong_available_temperature_value_degC": round(wrong_temperature, 1),
            "correct_point_air_temperature_max_degC": round(max_air, 1),
            "temperature_peak_difference_degC": round(temperature_difference, 1),
            "can_compute_apparent_heat_duration": has_path(wrong, "hourly.apparent_temperature"),
            "can_compute_warm_nights": has_path(wrong, "daily.temperature_2m_min"),
        },
        "rejected_or_insufficient_alternatives": REJECTED_ALTERNATIVES,
        "reference_solving_trace": [
            "Read metadata/files.csv to confirm candidate evidence files are package members.",
            "Read the locked event anchor and take the official window as 2024-03-31 through 2024-04-04.",
            "Inspect the local hourly heat-stress file and find hourly.apparent_temperature plus daily.temperature_2m_min.",
            "Compute max apparent temperature, count hourly apparent temperature values >= 40.0 degC, count daily minimum temperatures >= 27.0 degC, and compute max air temperature.",
            "Inspect the gridded aggregate file and identify stats.temperature_2m_max_c_max as the only available heat maximum while hourly apparent temperature and daily minimum temperature are absent.",
            "Compare 44.6 degC from the local point source with 35.3 degC from the substitute aggregate source, yielding a 9.3 degC peak-temperature difference.",
            "Reject precipitation, annual remote-sensing change, and burn-index files because they cannot reproduce the heat-stress calculation.",
        ],
    }

    rubric_criteria = [
        {
            "name": "Source-swap ruling and error class",
            "points": 4,
            "description": "Returns source_swap_fails and classifies the failure as missing_variable.",
            "partial_credit": "Partial credit for identifying a wrong source without naming the missing-variable failure.",
        },
        {
            "name": "Source paths and event window",
            "points": 4,
            "description": (
                "Gives the local heat-stress source, the gridded aggregate wrong source, the locked event-window "
                "source, and the 2024-03-31 to 2024-04-04 event window."
            ),
            "partial_credit": "Partial credit for two of the three required paths or a correct but incomplete event window.",
        },
        {
            "name": "Missing-field audit",
            "points": 4,
            "description": (
                "Identifies hourly.apparent_temperature as the first missing variable and daily.temperature_2m_min "
                "as another required missing field in the substitute source."
            ),
            "partial_credit": "Partial credit for one correct missing required field.",
        },
        {
            "name": "Calculations and numeric impact",
            "points": 4,
            "description": (
                "Reports 43.2 degC max apparent temperature, 16 apparent-temperature hours >= 40.0 degC, "
                "5 warm nights, 44.6 degC local air-temperature max, 35.3 degC wrong-source max, and 9.3 degC difference."
            ),
            "partial_credit": "Award proportional credit for correct metrics with degree-C values within 0.2 degC.",
        },
        {
            "name": "Rejected alternatives",
            "points": 2,
            "description": "Rejects precipitation, annual remote-sensing change, and burn-index alternatives with content-based reasons.",
            "partial_credit": "Partial credit for at least two correct package-grounded rejections.",
        },
        {
            "name": "Reference trace and output discipline",
            "points": 2,
            "description": (
                "Includes a concise package-relative solving trace and returns compact JSON without web evidence, "
                "hidden answers, absolute paths, invented values, or a generic heat-wave essay."
            ),
            "partial_credit": "Partial credit for a usable trace with minor formatting issues.",
        },
    ]

    computed_gt = {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": PACKAGE_ID,
        "task_type": "short_answer",
        "target_family": TARGET_FAMILY,
        "answer_type": "expert_error_attribution",
        "evaluation_mode": "hybrid",
        "eval_mode": "hybrid",
        "difficulty_level": "L3",
        "primary_gt": primary_gt,
        "intermediate_values": {
            "required_fields": required_fields,
            "wrong_source_present_heat_field": "stats.temperature_2m_max_c_max",
            "raw_wrong_temperature_value_degC": wrong_temperature,
            "raw_temperature_peak_difference_degC": temperature_difference,
            "correct_source_hourly_count": len(correct["hourly"]["time"]),
            "correct_source_daily_count": len(correct["daily"]["time"]),
        },
        "numeric_tolerances": {
            "max_apparent_temperature_degC": {"expected": round(max_apparent, 1), "tolerance": 0.2, "unit": "degC"},
            "max_air_temperature_degC": {"expected": round(max_air, 1), "tolerance": 0.2, "unit": "degC"},
            "wrong_available_temperature_value_degC": {
                "expected": round(wrong_temperature, 1),
                "tolerance": 0.2,
                "unit": "degC",
            },
            "temperature_peak_difference_degC": {
                "expected": round(temperature_difference, 1),
                "tolerance": 0.2,
                "unit": "degC",
            },
            "hours_apparent_temperature_ge_40c": {"expected": int(hours_apparent_ge_40), "tolerance": 0, "unit": "hours"},
            "warm_nights_tmin_ge_27c": {"expected": int(warm_nights), "tolerance": 0, "unit": "nights"},
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": SOURCE_FILES,
        },
        "rubric": {
            "total_points": 20,
            "criteria": rubric_criteria,
        },
    }

    output_path = task_dir() / "computed_gt.json"
    output_path.write_text(json.dumps(computed_gt, indent=2, sort_keys=True) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
